/**
 * Suburb lookup helpers.
 *
 * `src/data/suburbs.json` is generated by scripts/build-suburbs.mjs from the
 * ABS-derived postcode reference. Nothing at runtime reads the live site.
 */
import raw from '../data/suburbs.json';

export interface Suburb {
  key: string;
  name: string;
  postcode: string | null;
  region: string;
  lat: number | null;
  lon: number | null;
  /** Set where the postcode was hand-supplied and should be confirmed. */
  needsReview?: boolean;
  families: string[];
  oldSlugs: string[];
}

export const suburbs = raw as Suburb[];

const byKey = new Map(suburbs.map((s) => [s.key, s]));

/** Regions in display order for the /service-area/ index. */
export const regionOrder = [
  'Brisbane Inner City',
  'Brisbane North',
  'Brisbane South',
  'Brisbane West',
  'Redland',
  'Moreton Bay & Redcliffe',
  'Ipswich & West Moreton',
  'Logan & Beaudesert',
  'Gold Coast',
  'Stradbroke & Islands',
  'Sunshine',
];

export function getSuburb(key: string): Suburb | undefined {
  return byKey.get(key);
}

export function suburbsByRegion(): { region: string; suburbs: Suburb[] }[] {
  const groups = new Map<string, Suburb[]>();
  for (const s of suburbs) {
    if (!groups.has(s.region)) groups.set(s.region, []);
    groups.get(s.region)!.push(s);
  }
  const ordered = regionOrder
    .filter((r) => groups.has(r))
    .map((region) => ({
      region,
      // Bigger service areas first - inner Brisbane before the Gold Coast.
      suburbs: groups.get(region)!.sort((a, b) => a.name.localeCompare(b.name, 'en-AU')),
    }));
  // Any region the script produced that is not in the known order.
  const known = new Set(regionOrder);
  for (const [region, list] of groups) {
    if (!known.has(region)) ordered.push({ region, suburbs: list });
  }
  return ordered;
}

/** True when the suburb is inside one of the three core advertised areas. */
export function isCoreArea(suburb: Suburb): boolean {
  return (
    suburb.region.startsWith('Brisbane') ||
    suburb.region === 'Redland' ||
    suburb.region === 'Moreton Bay & Redcliffe' ||
    suburb.region === 'Ipswich & West Moreton' ||
    suburb.region === 'Logan & Beaudesert'
  );
}

/**
 * "in the {postcode} postcode area" / "on the {postcode} postcode" -
 * used in body copy so each suburb page reads as a real local page.
 */
export function postcodeLine(suburb: Suburb): string {
  if (!suburb.postcode) return 'and the surrounding suburbs';
  // Postcodes beginning 4 read as "the 4066 postcode"; that is how people say it.
  return `in the ${suburb.postcode} postcode`;
}

/** "4066" or null - for the compact fact strip. */
export function postcodeShort(suburb: Suburb): string | null {
  return suburb.postcode;
}
